enum LoginError: Error { case invalidPassword, locked(minutes: Int) }
do {
    try login(user, pwd)
} catch LoginError.locked(let m) {
    print("Try again in \(m) minutes")
} catch {
    print(error)
}

func load() throws(LoadError) -> Data { ... }
do { _ = try load() }
catch { handle(error) }  // error: LoadError

func read() throws -> String {
    let handle = try open(path)
    defer { handle.close() }
    return try handle.readAll()
}

