func f() {
    defer { print("1") }
    defer { print("2") }
    print("3")
}
f()

enum E: Error { case fail }
func f() throws {
    defer { print("cleanup") }
    throw E.fail
}
do { try f() } catch { print("caught") }

enum NetErr: Error { case timeout, code(Int) }
do { throw NetErr.code(404) }
catch NetErr.code(let c) where c >= 500 { print("server") }
catch NetErr.code(let c) { print("client \(c)") }
catch { print("other") }
